SELECT a.*,p.version AS portrait_version,b.version AS background_version,p.origin AS portrait_origin,b.origin AS background_origin,p.source_url AS portrait_source,b.source_url AS background_source,p.attribution AS portrait_attribution,b.attribution AS background_attribution,pf.state AS portrait_fetch_state,bf.state AS background_fetch_state FROM artist a LEFT JOIN artist_image p ON p.artist_id=a.id AND p.image_kind='PORTRAIT' LEFT JOIN artist_image b ON b.artist_id=a.id AND b.image_kind='BACKGROUND' LEFT JOIN artist_image_fetch pf ON pf.artist_id=a.id AND pf.image_kind='PORTRAIT' LEFT JOIN artist_image_fetch bf ON bf.artist_id=a.id AND bf.image_kind='BACKGROUND' WHERE a.id=?;
